<?php require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/data_insert.php';require_admin();verify_csrf();
$type=$_POST['upload_type']??'';$f=$_FILES['csv_file']??null;if(!in_array($type,['rankings','colleges','programs'],true)||!$f||$f['error']!==UPLOAD_ERR_OK)flash_redirect('admin/dashboard.php','error','Please choose a valid CSV file and upload type.');$pdo=db();$n=0;$handle=fopen($f['tmp_name'],'r');fgetcsv($handle);try{$pdo->beginTransaction();while(($row=fgetcsv($handle))!==false){if(!array_filter($row,fn($v)=>trim((string)$v)!==''))continue;if($type==='rankings'){[$sn,$y,$g,$ph,$note]=array_pad($row,5,null);$ok=insert_ranking(['ranking_body_short_name'=>$sn,'year'=>$y,'global_rank'=>$g,'ph_rank'=>$ph,'note'=>$note]);}elseif($type==='colleges'){[$name,$code,$pct,$y]=array_pad($row,4,null);$ok=insert_college(['name'=>$name,'short_code'=>$code,'contribution_percent'=>$pct,'year'=>$y]);}else{[$name,$cc,$nr,$score,$mov,$y]=array_pad($row,6,null);$ok=insert_program(['name'=>$name,'college_short_code'=>$cc,'national_rank'=>$nr,'score'=>$score,'movement'=>$mov,'year'=>$y]);}if($ok)$n++;}$pdo->prepare('INSERT INTO uploads_log(uploaded_by,filename,file_type,upload_type,rows_inserted) VALUES(?,?,?,?,?)')->execute([$_SESSION['user_id'],basename($f['name']),'csv',$type,$n]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();flash_redirect('admin/dashboard.php','error','CSV upload failed: '.$e->getMessage());}flash_redirect('admin/dashboard.php','success','Uploaded '.basename($f['name']).' — '.$n.' rows inserted.');
